local ffi=require('ffi')
if not pcall(ffi.typeof,'DFJHit') then
ffi.cdef[[
typedef void* DFJProbe; typedef void* DFJData;
typedef struct {int structSize;float locationX,locationY,locationZ,normalX,normalY,normalZ,velocityX,velocityY,velocityZ;int is_wet;} DFJHit;
void XPLMWorldToLocal(double,double,double,double*,double*,double*);
void XPLMLocalToWorld(double,double,double,double*,double*,double*);
DFJProbe XPLMCreateProbe(int);void XPLMDestroyProbe(DFJProbe);
int XPLMProbeTerrainXYZ(DFJProbe,float,float,float,DFJHit*);
DFJData XPLMFindDataRef(const char*);double XPLMGetDatad(DFJData);
]]
end
local X=ffi.load(SYSTEM=='IBM' and 'XPLM_64' or SYSTEM=='LIN' and 'Resources/plugins/XPLM_64.so' or 'Resources/plugins/XPLM.framework/XPLM')
local x,y,z=ffi.new('double[1]'),ffi.new('double[1]'),ffi.new('double[1]')
local hit=ffi.new('DFJHit[1]');hit[0].structSize=ffi.sizeof('DFJHit')
local probe=nil;local ti,pi=1,1;local cache={};local active=false
local function scalar(ctype,n) local a=ffi.new(ctype..'[1]',n);return ffi.string(a,ffi.sizeof(ctype)) end
local function str(s)
 local n=#s;local bytes={};repeat local b=n%128;n=math.floor(n/128);bytes[#bytes+1]=string.char(b+(n>0 and 128 or 0)) until n==0
 return table.concat(bytes)..s
end
local function save()
 -- Windows/X-Plane emploie le format little-endian du lecteur JoinFS 21003.
 if not ffi.abi('le') then error('Machine non little-endian') end
 local parts={scalar('int16_t',21003),scalar('int32_t',#tracks)}
 for _,t in ipairs(tracks) do
  parts[#parts+1]=string.char(1)..str(t.id)..str('DEFA')..str(t.model)..string.char(1)..scalar('int32_t',#t.frames)
  for _,p in ipairs(t.frames) do
   local row={string.char(1),scalar('double',p.time),scalar('double',p.lat*math.pi/180),scalar('double',p.lon*math.pi/180),scalar('double',p.altitude_m)}
   for _,v in ipairs({0,0,p.heading_deg*math.pi/180,p.east_ms or 0,0,p.north_ms or 0,0,0,0,0,0,0}) do row[#row+1]=scalar('float',v) end
   for _,v in ipairs({0,0,0,-16384,-16384}) do row[#row+1]=scalar('int16_t',v) end
   row[#row+1]=scalar('float',p.terrain_m);row[#row+1]=string.char(1);parts[#parts+1]=table.concat(row)
  end
 end
 parts[#parts+1]=scalar('int32_t',0)
 local f,why=io.open(output..'.tmp','wb');if not f then error(why) end
 local ok,err=f:write(table.concat(parts));f:close();if not ok then error(err) end
 -- Ne pas supprimer la précédente préparation si le remplacement échoue.
 local renamed,reason=os.rename(output..'.tmp',output)
 if not renamed then error('Remplacement du fichier impossible : '..tostring(reason)) end
 logMsg('DEFA Cezembre : terrain prepare. Ouvrir maintenant Ouvrir-Cezembre-JoinFS.cmd.')
end
function DEFA_Cezembre_arreter()
 if probe~=nil then X.XPLMDestroyProbe(probe);probe=nil end;active=false
end
function DEFA_Cezembre_preparer()
 if active then return end
 local latref=X.XPLMFindDataRef('sim/flightmodel/position/latitude');local lonref=X.XPLMFindDataRef('sim/flightmodel/position/longitude')
 if latref==nil or lonref==nil then return end
 local lat,lon=X.XPLMGetDatad(latref),X.XPLMGetDatad(lonref)
 if math.sqrt((lat-48.6769)^2+((lon+2.0714)*math.cos(lat*math.pi/180))^2)*60>25 then
  logMsg('DEFA Cezembre : rejoindre Saint-Malo/Cezembre avant de preparer le terrain.');return
 end
 probe=X.XPLMCreateProbe(0);if probe==nil then logMsg('DEFA Cezembre : sonde indisponible');return end
 cache={};ti=1;pi=1;active=true
end
function DEFA_Cezembre_tick()
 if not active then return end
 for _=1,24 do
  local t=tracks[ti]
  if not t then
   DEFA_Cezembre_arreter();local ok,err=pcall(save);if not ok then logMsg('DEFA Cezembre : '..tostring(err)) end;return
  end
  local p=t.frames[pi];local key=string.format('%.8f:%.8f',p.lat,p.lon);local altitude=cache[key]
  if not altitude then
   X.XPLMWorldToLocal(p.lat,p.lon,15000,x,y,z)
   if X.XPLMProbeTerrainXYZ(probe,x[0],y[0],z[0],hit)~=0 or hit[0].is_wet~=0 then
    logMsg('DEFA Cezembre : terrain absent ou eau pour '..t.id..' au point '..pi..'. Preparation arretee.');DEFA_Cezembre_arreter();return
   end
   X.XPLMLocalToWorld(hit[0].locationX,hit[0].locationY,hit[0].locationZ,x,y,z);altitude=z[0];cache[key]=altitude
  end
  p.altitude_m=altitude;p.terrain_m=altitude;pi=pi+1
  if pi>#t.frames then ti=ti+1;pi=1 end
 end
end
add_macro('DEFA Cezembre : preparer chien et personne','DEFA_Cezembre_preparer()')
do_every_frame('DEFA_Cezembre_tick()')
do_on_exit('DEFA_Cezembre_arreter()')
